INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch07$PT156-S2-Q7$batch07$, 156, 2, 7, $batch07$Method$batch07$, $batch07$Mr. Xu: The arctic squirrel gets so cold while hibernating that its blood temperature falls well below the temperature at which water freezes. Although the squirrel’s blood is about 70 percent water, the blood never freezes while the squirrel is hibernating. The squirrel’s blood, therefore, must contain a substance that prevents the blood from freezing at the temperature at which water freezes. Ms. Yerky: The blood contains no such substance. Laboratory experiments involving a number of animals, including the arctic squirrel, have shown that a vial of blood from any of the animals freezes at just the same temperature as does a vial of water.$batch07$, $batch07$Ms. Yerky’s response proceeds by$batch07$, $batch07$A$batch07$, true, $batch07$Batch 07; question text from local bank.$batch07$ FROM lr_sections s WHERE s.preptest=156 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT156-S2-Q7$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$A$batch07$, $batch07$presenting evidence that supports a conclusion inconsistent with Mr. Xu’s conclusion$batch07$, $batch07$Correct$batch07$, true FROM lr_questions q WHERE q.qid=$batch07$PT156-S2-Q7$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$A$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$B$batch07$, $batch07$showing that the evidence offered by Mr. Xu was collected by means of unreliable methods$batch07$, $batch07$Bad Description$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT156-S2-Q7$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$B$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$C$batch07$, $batch07$offering an alternative explanation for why the squirrel’s blood fails to freeze at the temperature at which water freezes$batch07$, $batch07$Bad Description$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT156-S2-Q7$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$C$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$D$batch07$, $batch07$showing that a key term used by Mr. Xu is ambiguous$batch07$, $batch07$Bad Description$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT156-S2-Q7$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$D$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$E$batch07$, $batch07$showing that the evidence provided by Mr. Xu has no bearing on the point at issue$batch07$, $batch07$Bad Description$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT156-S2-Q7$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$E$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT156-S2-Q7$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Conclusion$batch07$, $batch07$Ms. Yerky: the squirrel's blood contains no antifreeze substance.$batch07$), (1, $batch07$Evidence$batch07$, $batch07$In lab experiments, a vial of blood from each animal tested, including the arctic squirrel, froze at the same temperature as a vial of water.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$Mr. Xu reasons from a fact (the blood doesn't freeze) to a cause (it must contain a substance). Ms. Yerky doesn't dispute his fact or explain it another way. She simply offers evidence that the substance isn't there, which means her conclusion contradicts his.$batch07$), (3, $batch07$Goal$batch07$, $batch07$Something like "presents evidence for the opposite of Xu's conclusion".$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT156-S2-Q7$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$Her lab evidence supports "the blood contains no such substance", which is inconsistent with Xu's "must contain a substance".$batch07$), ($batch07$B$batch07$, $batch07$She never says Xu's evidence was gathered badly. She doesn't challenge his observation about the hibernating squirrel at all.$batch07$), ($batch07$C$batch07$, $batch07$This is the tempting one. If she had said "the blood doesn't freeze because the squirrel's body does X," C would be right. But she gives no explanation of why the blood stays liquid. She only denies Xu's.$batch07$), ($batch07$D$batch07$, $batch07$No key term is said to be ambiguous.$batch07$), ($batch07$E$batch07$, $batch07$She doesn't say Xu's evidence is irrelevant. She answers it with different evidence.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT156-S2-Q7$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
